from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span
from hourglass.merging import merge_spans
from hourglass.errors import ProjectError


def _check_inside(merged: List[Span], hours: Span) -> None:
    for block in merged:
        if block.start < hours.start:
            raise ProjectError(_outside(block))
        if block.end > hours.end:
            raise ProjectError(_outside(block))


def _outside(block: Span) -> str:
    return f"{format_span(block)} is outside opening hours"


def _uncovered(merged: List[Span], hours: Span) -> List[Span]:
    edges = [hours.start]
    for block in merged:
        edges += [block.start, block.end]
    edges.append(hours.end)
    pairs = zip(edges[::2], edges[1::2])
    return [Span(*pair) for pair in pairs if pair[0] < pair[1]]


def _label(hole: Span) -> str:
    return f"gap {format_span(hole)} ({hole.minutes} min)"


# ---
def find_gaps(worked: Iterable[Span], hours: Span) -> List[str]:
    """Label each uncovered stretch; ProjectError if outside."""
    merged = merge_spans(worked)
    _check_inside(merged, hours)
    return [_label(hole) for hole in _uncovered(merged, hours)]
