# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import find_gaps
from hourglass.errors import ProjectError

HOURS = parse_span("09:00-17:00")
LUNCH = ["gap 12:00-13:00 (60 min)"]


def gaps_for(*texts):
    return find_gaps([parse_span(t) for t in texts], HOURS)


class FindGapsTests(unittest.TestCase):
    def test_no_workers_is_one_gap(self):
        self.assertEqual(
            gaps_for(), ["gap 09:00-17:00 (480 min)"]
        )

    def test_full_cover_has_no_gaps(self):
        self.assertEqual(gaps_for("09:00-13:00", "12:00-17:00"), [])

    def test_gap_in_the_middle(self):
        result = gaps_for("09:00-12:00", "13:00-17:00")
        self.assertEqual(result, LUNCH)

    def test_gaps_at_edges_and_between(self):
        result = gaps_for("10:00-11:00", "12:00-16:00")
        self.assertEqual(result, [
            "gap 09:00-10:00 (60 min)",
            "gap 11:00-12:00 (60 min)",
            "gap 16:00-17:00 (60 min)"
        ])

    def test_unsorted_input(self):
        result = gaps_for("13:00-17:00", "09:00-12:00")
        self.assertEqual(result, LUNCH)

    def test_span_starting_early_raises(self):
        with self.assertRaises(ProjectError):
            gaps_for("08:00-12:00")

    def test_span_ending_late_raises(self):
        with self.assertRaises(ProjectError):
            gaps_for("12:00-18:00")
